+import Yoga, {type Node as YogaNode} from 'yoga-layout';
+import {type DOMElement, type DOMNode} from './dom.js';
+import applyStyles, {type Styles} from './styles.js';
+
+type Track =
+	| {kind: 'fixed'; size: number}
+	| {kind: 'auto'}
+	| {kind: 'fr'; min: number; fr: number};
+
+type Placement = {
+	columnStart: number;
+	columnEnd: number;
+	rowStart: number;
+	rowEnd: number;
+};
+
+const trackPattern = /minmax\\(\\s*(\\d+(?:\\.\\d+)?)\\s*,\\s*(\\d+(?:\\.\\d+)?fr|\\d+(?:\\.\\d+)?)\\s*\\)|(\\d+(?:\\.\\d+)?fr|\\d+(?:\\.\\d+)?|auto)/g;
+
+const parseTracks = (template: string | undefined): Track[] => {
+	if (!template) {
+		return [];
+	}
+
+	const tracks: Track[] = [];
+	for (const match of template.matchAll(trackPattern)) {
+		const min = match[1];
+		const max = match[2];
+		const value = match[3];
+		if (min && max) {
+			tracks.push(
+				max.endsWith('fr')
+					? {kind: 'fr', min: Number(min), fr: Number.parseFloat(max)}
+					: {kind: 'fixed', size: Number(max)},
+			);
+		} else if (value === 'auto') {
+			tracks.push({kind: 'auto'});
+		} else if (value?.endsWith('fr')) {
+			tracks.push({kind: 'fr', min: 0, fr: Number.parseFloat(value)});
+		} else if (value) {
+			tracks.push({kind: 'fixed', size: Number(value)});
+		}
+	}
+
+	return tracks;
+};
+
+const parseLine = (value: number | string | undefined): [number, number] | undefined => {
+	if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
+		return [value - 1, value];
+	}
+
+	if (typeof value === 'string') {
+		const match = /^(\\d+)\\s*\\/\\s*(\\d+)$/.exec(value);
+		if (match) {
+			const start = Number(match[1]);
+			const end = Number(match[2]);
+			if (start > 0 && end > start) {
+				return [start - 1, end - 1];
+			}
+		}
+	}
+};
+
+const overlaps = (a: Placement, b: Placement): boolean =>
+	a.columnStart < b.columnEnd &&
+	a.columnEnd > b.columnStart &&
+	a.rowStart < b.rowEnd &&
+	a.rowEnd > b.rowStart;
+
+const getPlacements = (children: DOMNode[], columnCount: number): Placement[] => {
+	const placements: Placement[] = [];
+	for (const child of children) {
+		const column = parseLine(child.style.gridColumn);
+		const row = parseLine(child.style.gridRow);
+		if (column && row) {
+			placements.push({
+				columnStart: column[0], columnEnd: column[1], rowStart: row[0], rowEnd: row[1],
+			});
+			continue;
+		}
+
+		let rowIndex = row?.[0] ?? 0;
+		let columnIndex = column?.[0] ?? 0;
+		while (true) {
+			const candidate: Placement = {
+				columnStart: columnIndex,
+				columnEnd: column?.[1] ?? columnIndex + 1,
+				rowStart: rowIndex,
+				rowEnd: row?.[1] ?? rowIndex + 1,
+			};
+			if (!placements.some(placement => overlaps(placement, candidate))) {
+				placements.push(candidate);
+				break;
+			}
+
+			if (column) {
+				rowIndex++;
+			} else if (row) {
+				columnIndex++;
+			} else {
+				columnIndex++;
+				if (columnIndex >= columnCount) {
+					columnIndex = 0;
+					rowIndex++;
+				}
+			}
+		}
+	}
+
+	return placements;
+};
+
+const resolveTracks = (
+	tracks: Track[],
+	available: number,
+	gap: number,
+	children: DOMNode[],
+	placements: Placement[],
+	isColumn: boolean,
+): number[] => {
+	const sizes = tracks.map(track => track.kind === 'fixed' ? track.size : track.kind === 'fr' ? track.min : 0);
+	for (const [index, track] of tracks.entries()) {
+		if (track.kind !== 'auto') {
+			continue;
+		}
+
+		for (const [childIndex, placement] of placements.entries()) {
+			const start = isColumn ? placement.columnStart : placement.rowStart;
+			const end = isColumn ? placement.columnEnd : placement.rowEnd;
+			if (start === index && end === index + 1) {
+				const yogaNode = children[childIndex].yogaNode;
+				sizes[index] = Math.max(sizes[index], isColumn ? yogaNode?.getComputedWidth() ?? 0 : yogaNode?.getComputedHeight() ?? 0);
+			}
+		}
+	}
+
+	const remaining = available - sizes.reduce((total, size) => total + size, 0) - gap * Math.max(0, tracks.length - 1);
+	const totalFr = tracks.reduce((total, track) => total + (track.kind === 'fr' ? track.fr : 0), 0);
+	if (remaining > 0 && totalFr > 0) {
+		for (const [index, track] of tracks.entries()) {
+			if (track.kind === 'fr') {
+				sizes[index] += remaining * track.fr / totalFr;
+			}
+		}
+	}
+
+	return sizes;
+};
+
+const resetManagedChildren = (node: DOMElement): void => {
+	for (const child of node.childNodes) {
+		if (child.nodeName !== '#text') {
+			resetManagedChildren(child);
+		}
+		if (!child.internal_gridManaged || !child.yogaNode) {
+			continue;
+		}
+
+		const yogaNode = child.yogaNode;
+		yogaNode.setPositionType(Yoga.POSITION_TYPE_RELATIVE);
+		yogaNode.setPosition(Yoga.EDGE_LEFT, undefined);
+		yogaNode.setPosition(Yoga.EDGE_TOP, undefined);
+		yogaNode.setWidthAuto();
+		yogaNode.setHeightAuto();
+		applyStyles(yogaNode, child.style);
+		child.internal_gridManaged = false;
+	}
+};
+
+const layoutGrid = (node: DOMElement): void => {
+	for (const child of node.childNodes) {
+		if (child.nodeName !== '#text') {
+			layoutGrid(child);
+		}
+	}
+
+	if (node.style.display !== 'grid' || !node.yogaNode) {
+		return;
+	}
+
+	const yogaNode = node.yogaNode;
+	const children = node.childNodes.filter(child => child.yogaNode);
+	let columns = parseTracks(node.style.gridTemplateColumns);
+	if (columns.length === 0) {
+		columns = [{kind: 'auto'}];
+	}
+	const placements = getPlacements(children, columns.length);
+	const rowCount = Math.max(0, ...placements.map(placement => placement.rowEnd));
+	let rows = parseTracks(node.style.gridTemplateRows);
+	while (rows.length < rowCount) {
+		rows.push({kind: 'auto'});
+	}
+	while (columns.length < Math.max(0, ...placements.map(placement => placement.columnEnd))) {
+		columns.push({kind: 'auto'});
+	}
+
+	const columnGap = yogaNode.getGap(Yoga.GUTTER_COLUMN).valueOf();
+	const rowGap = yogaNode.getGap(Yoga.GUTTER_ROW).valueOf();
+	const horizontalInsets = yogaNode.getComputedPadding(Yoga.EDGE_LEFT) + yogaNode.getComputedPadding(Yoga.EDGE_RIGHT) + yogaNode.getComputedBorder(Yoga.EDGE_LEFT) + yogaNode.getComputedBorder(Yoga.EDGE_RIGHT);
+	const verticalInsets = yogaNode.getComputedPadding(Yoga.EDGE_TOP) + yogaNode.getComputedPadding(Yoga.EDGE_BOTTOM) + yogaNode.getComputedBorder(Yoga.EDGE_TOP) + yogaNode.getComputedBorder(Yoga.EDGE_BOTTOM);
+	const columnSizes = resolveTracks(columns, Math.max(0, yogaNode.getComputedWidth() - horizontalInsets), columnGap, children, placements, true);
+	const explicitHeight = typeof node.style.height === 'number' || typeof node.style.height === 'string';
+	const rowAvailable = explicitHeight ? Math.max(0, yogaNode.getComputedHeight() - verticalInsets) : Number.POSITIVE_INFINITY;
+	const rowSizes = resolveTracks(rows, rowAvailable, rowGap, children, placements, false);
+	const contentHeight = rowSizes.reduce((total, size) => total + size, 0) + rowGap * Math.max(0, rowSizes.length - 1);
+	if (!explicitHeight) {
+		yogaNode.setHeight(contentHeight + verticalInsets);
+	}
+
+	for (const [index, child] of children.entries()) {
+		const childNode = child.yogaNode!;
+		const placement = placements[index];
+		const left = columnSizes.slice(0, placement.columnStart).reduce((total, size) => total + size, 0) + columnGap * placement.columnStart;
+		const top = rowSizes.slice(0, placement.rowStart).reduce((total, size) => total + size, 0) + rowGap * placement.rowStart;
+		const width = columnSizes.slice(placement.columnStart, placement.columnEnd).reduce((total, size) => total + size, 0) + columnGap * Math.max(0, placement.columnEnd - placement.columnStart - 1);
+		const height = rowSizes.slice(placement.rowStart, placement.rowEnd).reduce((total, size) => total + size, 0) + rowGap * Math.max(0, placement.rowEnd - placement.rowStart - 1);
+		childNode.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
+		childNode.setPosition(Yoga.EDGE_LEFT, left);
+		childNode.setPosition(Yoga.EDGE_TOP, top);
+		childNode.setWidth(width);
+		childNode.setHeight(height);
+		child.internal_gridManaged = true;
+	}
+};
+
+export const calculateLayout = (rootNode: DOMElement, width: number): void => {
+	resetManagedChildren(rootNode);
+	rootNode.yogaNode!.setWidth(width);
+	for (let iteration = 0; iteration < 3; iteration++) {
+		rootNode.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+		layoutGrid(rootNode);
+	}
+	rootNode.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+};
